enum Ex { Num(value: Int), Neg(inner: Ex), Bin(op: Str, lhs: Ex, rhs: Ex) }

type Parsed { node: Ex, pos: Int }

fn is_digit(c: Str) -> Bool {
  return "0123456789".contains(c)
}

fn tokenize(text: Str) -> List[Str] {
  var toks: List[Str] = []
  var cur = ""
  for c in text.chars() {
    if is_digit(c) {
      cur = cur + c
    } else {
      if cur != "" {
        toks = toks.push(cur)
        cur = ""
      }
      if c != " " {
        toks = toks.push(c)
      }
    }
  }
  if cur != "" {
    toks = toks.push(cur)
  }
  return toks
}

fn peek(toks: List[Str], pos: Int) -> Str {
  return toks.get_or(pos, "")
}

fn parse_primary(toks: List[Str], pos: Int) -> Result[Parsed, Str] {
  let tok = peek(toks, pos)
  if tok == "(" {
    let inner = parse_expr(toks, pos + 1)?
    if peek(toks, inner.pos) != ")" {
      return Err("syntax error")
    }
    return Ok(Parsed { node: inner.node, pos: inner.pos + 1 })
  }
  if tok == "" {
    return Err("syntax error")
  }
  if not is_digit(tok.slice(0, 1)) {
    return Err("syntax error")
  }
  let n = tok.to_int().ok_or("syntax error")?
  return Ok(Parsed { node: Ex.Num(value: n), pos: pos + 1 })
}

fn parse_unary(toks: List[Str], pos: Int) -> Result[Parsed, Str] {
  if peek(toks, pos) == "-" {
    let inner = parse_unary(toks, pos + 1)?
    return Ok(Parsed { node: Ex.Neg(inner: inner.node), pos: inner.pos })
  }
  return parse_primary(toks, pos)
}

fn parse_term(toks: List[Str], pos: Int) -> Result[Parsed, Str] {
  let head = parse_unary(toks, pos)?
  var node = head.node
  var p = head.pos
  while peek(toks, p) == "*" or peek(toks, p) == "/" {
    let op = peek(toks, p)
    let rhs = parse_unary(toks, p + 1)?
    node = Ex.Bin(op: op, lhs: node, rhs: rhs.node)
    p = rhs.pos
  }
  return Ok(Parsed { node: node, pos: p })
}

fn parse_expr(toks: List[Str], pos: Int) -> Result[Parsed, Str] {
  let head = parse_term(toks, pos)?
  var node = head.node
  var p = head.pos
  while peek(toks, p) == "+" or peek(toks, p) == "-" {
    let op = peek(toks, p)
    let rhs = parse_term(toks, p + 1)?
    node = Ex.Bin(op: op, lhs: node, rhs: rhs.node)
    p = rhs.pos
  }
  return Ok(Parsed { node: node, pos: p })
}

fn apply(op: Str, a: Int, b: Int) -> Result[Int, Str] {
  if op == "+" {
    return Ok(a + b)
  }
  if op == "-" {
    return Ok(a - b)
  }
  if op == "*" {
    return Ok(a * b)
  }
  if b == 0 {
    return Err("division by zero")
  }
  return Ok(a / b)
}

fn evaluate(node: Ex) -> Result[Int, Str] {
  return match node {
    Ex.Num(v) => Ok(v),
    Ex.Neg(inner) => Ok(0 - evaluate(inner)?),
    Ex.Bin(op, lhs, rhs) => apply(op: op, a: evaluate(lhs)?, b: evaluate(rhs)?),
  }
}

pub fn calc(expr: Str) -> Result[Int, Str] {
  let toks = tokenize(expr)
  let parsed = parse_expr(toks, 0)?
  if parsed.pos != toks.len() {
    return Err("syntax error")
  }
  return evaluate(parsed.node)
}
